54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
65	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
66	     * stored lower-cased.
67	     */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        validateRequiredOwnerFields(ownerFieldsDto);
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
121	        owner.setTelephone(normalizedTelephone);
122	        rejectDuplicateTelephone(normalizedTelephone);
123	        owner.setEmail(normalizeEmail(owner.getEmail()));
124	        if (owner.getRegistrationDate() == null) {
125	            owner.setRegistrationDate(LocalDate.now());
126	        }
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
137	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
138	        if (currentOwner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        currentOwner.setAddress(ownerFieldsDto.getAddress());
142	        currentOwner.setCity(ownerFieldsDto.getCity());
143	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
144	        currentOwner.setLastName(ownerFieldsDto.getLastName());
145	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
146	        this.clinicService.saveOwner(currentOwner);
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Transactional
152	    @Override
153	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        this.clinicService.deleteOwner(owner);
159	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        HttpHeaders headers = new HttpHeaders();
170	        Pet pet = petMapper.toPet(petFieldsDto);
171	        owner.setId(ownerId);
172	        pet.setOwner(owner);
173	        pet.getType().setName(null);
174	        this.clinicService.savePet(pet);
175	        PetDto petDto = petMapper.toPetDto(pet);
176	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
177	            .buildAndExpand(pet.getId()).toUri());
178	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner != null) {
186	            Pet currentPet = this.clinicService.findPetById(petId);
187	            if (currentPet != null) {
188	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
189	                currentPet.setName(petFieldsDto.getName());
190	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
191	                this.clinicService.savePet(currentPet);
192	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
193	            }
194	        }
195	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
201	        HttpHeaders headers = new HttpHeaders();
202	        Visit visit = visitMapper.toVisit(visitFieldsDto);
203	        Pet pet = new Pet();
204	        pet.setId(petId);
205	        visit.setPet(pet);
206	        this.clinicService.saveVisit(visit);
207	        VisitDto visitDto = visitMapper.toVisitDto(visit);
208	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
209	            .buildAndExpand(visit.getId()).toUri());
210	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
211	    }
212	
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
217	        Owner owner = this.clinicService.findOwnerById(ownerId);
218	        if (owner != null) {
219	            Pet pet = owner.getPet(petId);
220	            if (pet != null) {
221	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
222	            }
223	        }
224	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
225	    }
226	
227	    /**
228	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
229	     * offending field is collected so the caller learns exactly which values must be supplied.
230	     *
231	     * @param ownerFieldsDto the submitted owner payload
232	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
233	     *         telephone is missing or blank
234	     */
235	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
236	        List<String> missingFields = new ArrayList<>();
237	        if (isBlank(ownerFieldsDto.getFirstName())) {
238	            missingFields.add("firstName");
239	        }
240	        if (isBlank(ownerFieldsDto.getLastName())) {
241	            missingFields.add("lastName");
242	        }
243	        if (isBlank(ownerFieldsDto.getAddress())) {
244	            missingFields.add("address");
245	        }
246	        if (isBlank(ownerFieldsDto.getCity())) {
247	            missingFields.add("city");
248	        }
249	        if (isBlank(ownerFieldsDto.getTelephone())) {
250	            missingFields.add("telephone");
251	        }
252	        if (!missingFields.isEmpty()) {
253	            throw new MissingOwnerFieldsException(missingFields);
254	        }
255	    }
256	
257	    private boolean isBlank(String value) {
258	        return value == null || value.isBlank();
259	    }
260	
261	    /**
262	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
263	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
264	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
265	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
266	     * stored and returned.
267	     *
268	     * @param telephone the raw telephone value from the request
269	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
270	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
271	     */
272	    private String normalizeTelephone(String telephone) {
273	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
274	        String e164;
275	        if (cleaned.startsWith("+")) {
276	            e164 = cleaned;
277	        } else {
278	            String national = cleaned;
279	            if (national.startsWith("0")) {
280	                national = national.substring(1);
281	            }
282	            e164 = "+61" + national;
283	        }
284	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
285	            throw new InvalidOwnerFieldsException(List.of("telephone"));
286	        }
287	        return e164;
288	    }
289	
290	    /**
291	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
292	     * left unset. When a value is present it must be a syntactically valid address; the normalized
293	     * form stored and returned is the value lower-cased.
294	     *
295	     * @param email the raw email value from the request, or {@code null} when none was supplied
296	     * @return the lower-cased email, or {@code null} when no email was supplied
297	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
298	     */
299	    private String normalizeEmail(String email) {
300	        if (email == null || email.isBlank()) {
301	            return null;
302	        }
303	        if (!EMAIL_PATTERN.matcher(email).matches()) {
304	            throw new InvalidOwnerFieldsException(List.of("email"));
305	        }
306	        return email.toLowerCase(Locale.ROOT);
307	    }
308	
309	    /**
310	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
311	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
312	     * directly and is therefore independent of the punctuation a caller supplied.
313	     *
314	     * @param e164Telephone the E.164 telephone of the owner being created
315	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
316	     */
317	    private void rejectDuplicateTelephone(String e164Telephone) {
318	        boolean inUse = this.clinicService.findAllOwners().stream()
319	            .map(Owner::getTelephone)
320	            .filter(existing -> existing != null)
321	            .anyMatch(e164Telephone::equals);
322	        if (inUse) {
323	            throw new DuplicateOwnerTelephoneException(e164Telephone);
324	        }
325	    }
326	}
